<?php
require_once __DIR__.'/legacy_operational_read.php';
if(lop_ready($koneksi)){
    $groups=$koneksi->query("SELECT g.*,b.id batch_id,COUNT(o.id) owners FROM legacy_op_groups g JOIN legacy_op_owners o ON o.group_id=g.id AND o.unit_id=g.unit_id JOIN legacy_full_batches b ON b.id=o.batch_id AND b.unit_id=o.unit_id WHERE b.state='completed' GROUP BY g.id,b.id ORDER BY g.unit_id,g.code")->fetch_all(MYSQLI_ASSOC);
    if($groups){ ?><section class="main-card" style="margin-top:24px"><h2>Kelompok dari Legacy</h2><p>Rekening khusus dan kelompok nonakademik ditampung terpisah dari peserta kenaikan kelas.</p><div class="table-wrapper"><table><thead><tr><th>Kelompok</th><th>Jenis</th><th>Identitas</th><th>Tindakan</th></tr></thead><tbody><?php foreach($groups as $g): ?><tr><td><?= htmlspecialchars($g['label']) ?><?php if(unit_all_readonly()): ?> · <?= htmlspecialchars(unit_label((int)$g['unit_id'])) ?><?php endif; ?><br><small><?= htmlspecialchars(implode(', ',json_decode($g['aliases'],true))) ?></small></td><td><?= htmlspecialchars(['academic'=>'Kelas akademik','psb'=>'PSB','out'=>'Siswa keluar','alumni'=>'Alumni','account'=>'Rekening khusus','legacy'=>'Perlu klasifikasi'][$g['kind']]) ?></td><td><?= (int)$g['owners'] ?></td><td><a class="btn btn-ghost" href="legacy_accounts.php?batch=<?= htmlspecialchars($g['batch_id']) ?>">Lihat Rekening &amp; Transaksi</a></td></tr><?php endforeach; ?></tbody></table></div></section><?php }
}
